import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.sql.*;
public class ViewTransferFrame extends JFrame{JTable table;DefaultTableModel model;public ViewTransferFrame(){setTitle("Banking Management System - VIEW TRANSFERS");setSize(1050,520);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new BorderLayout());p.setBackground(new Color(230,240,255));JLabel h=new JLabel("VIEW TRANSFERS",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBorder(BorderFactory.createEmptyBorder(15,10,15,10));p.add(h,BorderLayout.NORTH);String[] cols={"ID","FROM ACCOUNT","TO ACCOUNT","AMOUNT","DATE","DESCRIPTION"};model=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);p.add(new JScrollPane(table),BorderLayout.CENTER);JButton r=new JButton("REFRESH"),c=new JButton("CLOSE");JPanel bp=new JPanel();bp.add(r);bp.add(c);p.add(bp,BorderLayout.SOUTH);r.addActionListener(e->load());c.addActionListener(e->dispose());add(p);load();}void load(){model.setRowCount(0);try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT TRANSFER_ID,FROM_ACCOUNT_ID,TO_ACCOUNT_ID,AMOUNT,TRANSFER_DATE,DESCRIPTION FROM BANK_TRANSFERS ORDER BY TRANSFER_ID");ResultSet r=q.executeQuery()){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getInt(2),r.getInt(3),r.getDouble(4),r.getDate(5),r.getString(6)});}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
